  car.add(glow);
  car.userData.glow = glow;
  scene.add(car);
  const threat = {
    mesh: car,
    alive: true,
    hp: boss ? 140 : 48,
    maxHp: boss ? 140 : 48,
    speed: boss ? 18 : 12,
    strafe: Math.random() * Math.PI * 2,
    attackCooldown: 0,
