600: function updatePlayer(dt) {
601:   const carMode = player.mode === 'car';
602:   const steer = (keysDown.right() ? 1 : 0) - (keysDown.left() ? 1 : 0);
603: 
604:   if (carMode) {
605:     const throttle = (keysDown.accelerate() ? 1 : 0) - (keysDown.brake() ? 1 : 0);
606:     if (Math.abs(steer) > 0) {
607:       player.heading += steer * 1.8 * dt;
608:     }
609:     const forward = new THREE.Vector3(Math.sin(player.heading), 0, -Math.cos(player.heading));
610:     const accelerating = throttle !== 0;
611:     if (accelerating) {
612:       const accel = throttle > 0 ? 24 : 18;
613:       player.speed += accel * throttle * dt;
614:       player.engine = Math.max(0, player.engine - 1.2 * dt);
615:     } else {
616:       player.speed *= 0.97;
617:       player.engine = Math.min(100, player.engine + 0.7 * dt);
618:     }
619:     if (keysDown.boost() && player.boost > 0) {
620:       player.speed += 18 * dt;
621:       player.boost = Math.max(0, player.boost - 32 * dt);
622:       player.charge = Math.max(0, player.charge - 0.8 * dt);
623:     } else {
624:       player.boost = Math.min(100, player.boost + 12 * dt);
625:     }
626:     player.speed = THREE.MathUtils.clamp(player.speed, -14, 42);
627:     playerCar.position.addScaledVector(forward, player.speed * dt);
628:     playerCar.position.x = clampToMap(playerCar.position.x);
629:     playerCar.position.z = clampToMap(playerCar.position.z);
630:     playerCar.rotation.y = player.heading;
631:     playerCar.visible = true;
632:     agent.visible = false;
633:     player.x = playerCar.position.x;
634:     player.z = playerCar.position.z;
635:   } else {
636:     const movement = new THREE.Vector3((keysDown.right() ? 1 : 0) - (keysDown.left() ? 1 : 0), 0, (keysDown.accelerate() ? 1 : 0) - (keysDown.brake() ? 1 : 0));
637:     const stepSpeed = 16;
638:     if (movement.lengthSq() > 0.01) {
639:       movement.normalize();
640:       const headingTarget = Math.atan2(movement.x, -movement.z);
641:       player.heading = THREE.MathUtils.lerp(player.heading, headingTarget, 0.18);
642:       const moveVec = new THREE.Vector3(movement.x * stepSpeed * dt, 0, movement.z * stepSpeed * dt);
643:       agent.position.add(moveVec);
644:       agent.position.x = clampToMap(agent.position.x);
645:       agent.position.z = clampToMap(agent.position.z);
646:       agent.rotation.y = player.heading + Math.PI;
647:     }
648:     agent.visible = true;
649:     playerCar.visible = false;
650:     player.x = agent.position.x;
651:     player.z = agent.position.z;
652:     playerCar.position.x = player.x;
653:     playerCar.position.z = player.z;
654:   }
655: 
656:   const target = player.mode === 'car' ? playerCar.position : agent.position;
657:   target.y = 0;
658: 
659:   if (player.fireCooldown > 0) player.fireCooldown -= dt;
660:   player.charge = Math.min(100, player.charge + 0.15 * dt);
661:   player.engine = Math.max(0, player.engine - (player.mode === 'car' && Math.abs(player.speed) > 5 ? 0.18 : 0) * dt * 60);
662: }
