689: function drawMinimap() {
690:   const ctx = ui.mapCanvas.getContext('2d');
691:   const w = ui.mapCanvas.width, h = ui.mapCanvas.height;
692:   ctx.clearRect(0, 0, w, h);
693:   ctx.fillStyle = 'rgba(10, 18, 22, 0.8)';
694:   ctx.fillRect(0, 0, w, h);
695:   ctx.strokeStyle = 'rgba(187, 214, 203, 0.35)';
696:   ctx.lineWidth = 1;
697:   for (let x = 0; x <= 4; x++) {
698:     ctx.beginPath();
699:     ctx.moveTo((w / 4) * x, 0); ctx.lineTo((w / 4) * x, h); ctx.stroke();
700:   }
701:   for (let y = 0; y <= 4; y++) {
702:     ctx.beginPath();
703:     ctx.moveTo(0, (h / 4) * y); ctx.lineTo(w, (h / 4) * y); ctx.stroke();
704:   }
705:   ctx.fillStyle = '#7ba6b0';
706:   ctx.fillRect(w * 0.28, h * 0.28, w * 0.44, h * 0.44);
707:   ctx.fillStyle = '#2d3d32';
708:   ctx.fillRect(w * 0.22, h * 0.22, w * 0.56, h * 0.56);
709: 
710:   const xToMap = (x) => ((x + 160) / 320) * w;
711:   const zToMap = (z) => ((z + 160) / 320) * h;
712: 
713:   ctx.strokeStyle = 'rgba(220, 212, 176, 0.7)';
714:   for (let roadX = -120; roadX <= 120; roadX += 48) {
715:     const fx = xToMap(roadX);
716:     ctx.beginPath(); ctx.moveTo(fx, 0); ctx.lineTo(fx, h); ctx.stroke();
717:   }
718:   for (let roadZ = -120; roadZ <= 120; roadZ += 48) {
719:     const fz = zToMap(roadZ);
720:     ctx.beginPath(); ctx.moveTo(0, fz); ctx.lineTo(w, fz); ctx.stroke();
721:   }
722: 
723:   for (const threat of enemyCars) {
724:     if (!threat.alive) continue;
725:     const px = xToMap(threat.mesh.position.x), py = zToMap(threat.mesh.position.z);
726:     ctx.fillStyle = threat.boss ? '#ff8e6f' : '#ff5d5d';
727:     ctx.beginPath();
728:     ctx.arc(px, py, threat.boss ? 5 : 4, 0, Math.PI * 2);
729:     ctx.fill();
730:   }
731: 
732:   const px = xToMap(playerCar.position.x || agent.position.x), py = zToMap(playerCar.position.z || agent.position.z);
733:   ctx.save();
734:   ctx.translate(px, py);
735:   ctx.rotate(-player.heading);
736:   ctx.fillStyle = '#a9e7c3';
737:   ctx.beginPath();
738:   ctx.moveTo(0, -7); ctx.lineTo(5, 7); ctx.lineTo(0, 5); ctx.lineTo(-5, 7); ctx.closePath();
739:   ctx.fill();
740:   ctx.restore();
741: }
