346: function updateTouchStick(event) {
347:   const rect = ui.stickZone.getBoundingClientRect();
348:   const centerX = rect.left + rect.width / 2;
349:   const centerY = rect.top + rect.height / 2;
350:   const radius = (rect.width - 26 - 48) / 2;
351:   const dx = event.clientX - centerX;
352:   const dy = event.clientY - centerY;
353:   const distance = Math.hypot(dx, dy);
354:   const scale = distance > radius ? radius / distance : 1;
355:   const x = dx * scale;
356:   const y = dy * scale;
357:   ui.stickKnob.style.transform = `translate(calc(-50% + ${x}px), calc(-50% + ${y}px))`;
358:   touchKeys.a = x < -radius * 0.2;
359:   touchKeys.d = x > radius * 0.2;
360:   touchKeys.w = y < -radius * 0.2;
361:   touchKeys.s = y > radius * 0.2;
362: }
