651: function updatePlayer(dt) {
652:   const carMode = player.mode === 'car';
653:   const steer = (keysDown.right() ? 1 : 0) - (keysDown.left() ? 1 : 0);
654: 
655:   if (carMode) {
656:     const throttle = (keysDown.accelerate() ? 1 : 0) - (keysDown.brake() ? 1 : 0);
657:     if (Math.abs(steer) > 0) {
658:       player.heading += steer * 1.8 * dt;
659:     }
660:     const forward = new THREE.Vector3(Math.sin(player.heading), 0, -Math.cos(player.heading));
661:     const accelerating = throttle !== 0;
662:     if (accelerating) {
663:       const accel = throttle > 0 ? 24 : 18;
664:       player.speed += accel * throttle * dt;
665:       player.engine = Math.max(0, player.engine - 1.2 * dt);
666:     } else {
667:       player.speed *= 0.97;
668:       player.engine = Math.min(100, player.engine + 0.7 * dt);
669:     }
670:     if (keysDown.boost() && player.boost > 0) {
671:       player.speed += 18 * dt;
672:       player.boost = Math.max(0, player.boost - 32 * dt);
673:       player.charge = Math.max(0, player.charge - 0.8 * dt);
674:     } else {
675:       player.boost = Math.min(100, player.boost + 12 * dt);
676:     }
677:     player.speed = THREE.MathUtils.clamp(player.speed, -14, 42);
678:     playerCar.position.addScaledVector(forward, player.speed * dt);
679:     playerCar.position.x = clampToMap(playerCar.position.x);
680:     playerCar.position.z = clampToMap(playerCar.position.z);
681:     playerCar.rotation.y = player.heading;
682:     playerCar.visible = true;
683:     agent.visible = false;
684:     player.x = playerCar.position.x;
685:     player.z = playerCar.position.z;
686:   } else {
687:     const movement = new THREE.Vector3((keysDown.right() ? 1 : 0) - (keysDown.left() ? 1 : 0), 0, (keysDown.accelerate() ? 1 : 0) - (keysDown.brake() ? 1 : 0));
688:     const stepSpeed = 16;
689:     if (movement.lengthSq() > 0.01) {
690:       movement.normalize();
691:       const headingTarget = Math.atan2(movement.x, -movement.z);
692:       player.heading = THREE.MathUtils.lerp(player.heading, headingTarget, 0.18);
693:       const moveVec = new THREE.Vector3(movement.x * stepSpeed * dt, 0, movement.z * stepSpeed * dt);
694:       agent.position.add(moveVec);
695:       agent.position.x = clampToMap(agent.position.x);
696:       agent.position.z = clampToMap(agent.position.z);
697:       agent.rotation.y = player.heading + Math.PI;
698:     }
699:     agent.visible = true;
700:     playerCar.visible = false;
701:     player.x = agent.position.x;
702:     player.z = agent.position.z;
703:     playerCar.position.x = player.x;
704:     playerCar.position.z = player.z;
705:   }
706: 
707:   const target = player.mode === 'car' ? playerCar.position : agent.position;
708:   target.y = 0;
709: 
710:   if (player.fireCooldown > 0) player.fireCooldown -= dt;
711:   player.charge = Math.min(100, player.charge + 0.15 * dt);
712:   player.engine = Math.max(0, player.engine - (player.mode === 'car' && Math.abs(player.speed) > 5 ? 0.18 : 0) * dt * 60);
713: }
